function availableGroups(){
var out=[];
(config.chatterIds||[]).forEach(function(chatter){
(config.robots||[]).filter(function(r){return r.enabled!==false&&!r.onlySubAgent&&!r.onlyTeamMember}).forEach(function(r){
var acp='acp-'+(r.name||'').replace(/ |　/g,'_');
out.push({id:[chatter,acp].sort().join(''),label:'[MolaChat] '+(r.name||'未命名')});
});
});
(channelBindingTargets.sessions||[]).filter(function(s){return s.active&&s.groupId}).forEach(function(s){
if(!out.some(function(item){return item.id===s.groupId}))out.push({id:s.groupId,label:'[Starweave] '+(s.robotName||'未命名')});
});
return out;
}

