async function deleteAgentGateway(index){var item=(config.agentGateways||[])[index];if(item&&await showConfirm('删除智能体网关「'+(item.name||item.id)+'」后，外部连接将无法再使用该鉴权码。',{title:'删除智能体网关？',confirmText:'删除网关',danger:true})){config.agentGateways.splice(index,1);markDirty();render()}}

function nextChannelId(){var index=(config.channels||[]).length+1,names=(config.channels||[]).map(function(item){return String(item.id||'').trim()}),candidate='wecom-'+index;while(names.indexOf(candidate)>=0){index+=1;candidate='wecom-'+index}return candidate}
function nextChannelCopyId(sourceId){var source=String(sourceId||'wecom').trim()||'wecom',match=source.match(/^(.*)-(\d+)$/),base=match?match[1]:source,next=match?parseInt(match[2],10)+1:1,names=(config.channels||[]).map(function(item){return String(item.id||'').trim()}),candidate=base+'-'+next;while(names.indexOf(candidate)>=0){next+=1;candidate=base+'-'+next}return candidate}
function createChannelArchiveId(){if(window.crypto&&window.crypto.randomUUID)return window.crypto.randomUUID();var bytes=new Uint8Array(16);window.crypto.getRandomValues(bytes);bytes[6]=(bytes[6]&15)|64;bytes[8]=(bytes[8]&63)|128;return Array.from(bytes).map(function(value,index){return ([4,6,8,10].indexOf(index)>=0?'-':'')+value.toString(16).padStart(2,'0')}).join('')}
function normalizeChannelOutboundTargets(ch){if(!ch)return[];if(!Array.isArray(ch.outboundTargets))ch.outboundTargets=[{id:String(ch.id||'').trim(),chatId:String(ch.defaultChatId||'').trim(),description:'企业微信默认主动推送目标'}];return ch.outboundTargets}
function isValidChannelOutboundTargetId(id){return /^[\p{L}\p{N}_-]{1,120}$/u.test(String(id||''))}
function defaultChannelOutboundTarget(channelId){return {id:String(channelId||'').trim(),chatId:'',description:'企业微信默认主动推送目标'}}
function newChannelDraft(){var id=nextChannelId();return {id:id,archiveId:createChannelArchiveId(),type:'WECOM_WS',enabled:true,inboundEnabled:true,privateChatEnabled:true,userBehavior:'QUEUE',botId:'',secret:'',wsUrl:'wss://openws.work.weixin.qq.com',outboundTargets:[defaultChannelOutboundTarget(id)],knownChatTargets:[],binding:{type:'MAIN',instanceId:channelRuntime.instanceId||((curInstance&&curInstance.instanceId)||''),groupId:'',teamId:'',teamMemberId:'',teamMemberSelection:'FIXED'}}}
function openChannelDialog(i,mode){
channelDialogMode=mode==='copy'?'copy':(i>=0?'edit':'add');channelDialogIndex=channelDialogMode==='edit'?i:-1;channelDialogDraft=i>=0?JSON.parse(JSON.stringify(config.channels[i])):newChannelDraft();
channelDialogSourceId=i>=0?String(config.channels[i].id||'').trim():'';
normalizeChannelOutboundTargets(channelDialogDraft);
if(channelDialogMode==='copy'){channelDialogDraft.id=nextChannelCopyId(channelDialogDraft.id);channelDialogDraft.archiveId=createChannelArchiveId();channelDialogDraft.secret='';channelDialogDraft.outboundTargets=[defaultChannelOutboundTarget(channelDialogDraft.id)];channelDialogDraft.knownChatTargets=[];if(channelDialogDraft.binding)channelDialogDraft.binding.conversationMappings=[]}
if(!channelDialogDraft.binding)channelDialogDraft.binding={type:'MAIN',instanceId:channelRuntime.instanceId||((curInstance&&curInstance.instanceId)||''),groupId:'',teamId:'',teamMemberId:'',teamMemberSelection:'FIXED'};
if(!channelDialogDraft.binding.teamMemberSelection)channelDialogDraft.binding.teamMemberSelection='FIXED';
document.getElementById('channelDialogTitle').textContent=channelDialogMode==='copy'?'复制消息渠道':(channelDialogMode==='edit'?'编辑消息渠道':'连接企业微信');
document.getElementById('channelDialogSubmit').innerHTML=channelDialogMode==='copy'?'<span class="material-icons">content_copy</span>复制消息渠道':'<span class="material-icons">save</span>'+(channelDialogMode==='edit'?'保存消息渠道':'创建消息渠道');
renderChannelDialogBody();showDialog('channelDialog');startChannelKnownTargetsRefresh();
}
function renderChannelDialogBody(){
var ch=channelDialogDraft;if(!ch)return;var b=ch.binding,groups=availableGroups(),selectedGroup=groups.filter(function(item){return item.id===b.groupId})[0];
var groupOpts='<option value="">选择独立智能体</option>'+groups.map(function(item){return '<option value="'+esc(item.id)+'"'+(item.id===b.groupId?' selected':'')+'>'+esc(item.label)+'</option>'}).join('');if(b.groupId&&!selectedGroup)groupOpts+='<option value="'+esc(b.groupId)+'" selected>当前智能体（不可用）</option>';
var teams=channelBindingTargets.teams||[],selectedTeam=teams.filter(function(item){return item.id===b.teamId})[0];
var teamOpts='<option value="">选择 Team</option>'+teams.map(function(item){return '<option value="'+esc(item.id)+'"'+(item.id===b.teamId?' selected':'')+'>'+esc(item.name||'未命名团队')+' ['+esc(item.state||'UNKNOWN')+']</option>'}).join('');if(b.teamId&&!selectedTeam)teamOpts+='<option value="'+esc(b.teamId)+'" selected>当前团队（不可用）</option>';
var captainMode=selectedTeam&&(selectedTeam.mode||'NORMAL')==='CAPTAIN';if(captainMode){b.teamMemberSelection='FIXED';b.teamMemberId=selectedTeam.captainTeamMemberId||''}var members=selectedTeam&&selectedTeam.members?selectedTeam.members:[],selectedMember=members.filter(function(item){return item.id===b.teamMemberId})[0];
var memberOpts='<option value="">选择团队成员</option>'+members.map(function(item){return '<option value="'+esc(item.id)+'"'+(item.id===b.teamMemberId?' selected':'')+'>'+esc(item.name||'未命名成员')+' ['+esc(item.state||'UNKNOWN')+']</option>'}).join('');if(b.teamMemberId&&!selectedMember)memberOpts+='<option value="'+esc(b.teamMemberId)+'" selected>当前成员（不可用）</option>';
var outboundTargetSection=renderChannelOutboundTargetList(ch),mappingSection=b.type==='TEAM_MEMBER'&&b.teamMemberSelection==='CONVERSATION_MAPPING'&&!captainMode?renderChannelConversationMappings(ch,members):'';
var bindingFields=b.type==='MAIN'?'<div class="field-group"><label>选择智能体 *</label><select onchange="channelDialogDraft.binding.groupId=this.value">'+groupOpts+'</select></div>':b.type==='TEAM_MEMBER'?'<div class="field-group"><label>Fast Team *</label><select onchange="setChannelDraftTeam(this.value)">'+teamOpts+'</select></div>'+(captainMode?'<div class="field-group"><label>成员选择方式</label><input value="固定：队长" readonly><div class="toggle-desc">队长模式的外部消息只由唯一队长承接，不自动切换成员。</div></div><div class="field-group"><label>团队队长</label><select disabled>'+memberOpts+'</select></div>':'<div class="field-group"><label>成员选择方式 *</label><select onchange="setChannelDraftMemberSelection(this.value)"><option value="FIXED"'+((b.teamMemberSelection||'FIXED')==='FIXED'?' selected':'')+'>指定团队成员</option><option value="RANDOM"'+(b.teamMemberSelection==='RANDOM'?' selected':'')+'>随机选择成员</option><option value="AFFINITY"'+(b.teamMemberSelection==='AFFINITY'?' selected':'')+'>按会话固定分配</option><option value="CONVERSATION_MAPPING"'+(b.teamMemberSelection==='CONVERSATION_MAPPING'?' selected':'')+'>按会话路由</option></select><div class="toggle-desc">'+(b.teamMemberSelection==='CONVERSATION_MAPPING'?'按下方映射交给指定成员，未绑定会话直接返回提示。':'单聊按 userId、群聊按 chatId 分配；优先占用空闲成员，全部占用后按 Hash 共享。')+'</div></div>'+((b.teamMemberSelection||'FIXED')==='FIXED'?'<div class="field-group"><label>团队成员 *</label><select onchange="channelDialogDraft.binding.teamMemberId=this.value">'+memberOpts+'</select></div>':'')):'';
document.getElementById('channelDialogBody').innerHTML='<div class="section-title">连接信息</div><div class="grid-2"><div class="field-group"><label>渠道名称 *</label><input id="channelDraftId" value="'+esc(ch.id||'')+'" oninput="setChannelDraftId(this.value)" placeholder="wecom-main"></div><div class="field-group"><label>Bot ID *</label><input id="channelDraftBotId" value="'+esc(ch.botId||'')+'" oninput="channelDialogDraft.botId=this.value"></div><div class="field-group"><label>Secret *</label><input id="channelDraftSecret" type="password" value="'+esc(ch.secret||'')+'" oninput="channelDialogDraft.secret=this.value" placeholder="保存后自动掩码"></div><div class="field-group"><label>WebSocket URL</label><input value="'+esc(ch.wsUrl||'wss://openws.work.weixin.qq.com')+'" oninput="channelDialogDraft.wsUrl=this.value"></div></div><div class="section-title">消息处理</div><div class="grid-2"><div class="field-group"><label>消息交给谁处理 *</label><select onchange="setChannelDraftBindingType(this.value)"><option value="MAIN"'+(b.type==='MAIN'?' selected':'')+'>独立智能体</option><option value="TEAM_MEMBER"'+(b.type==='TEAM_MEMBER'?' selected':'')+'>团队成员</option></select></div>'+bindingFields+'<div class="field-group"><label>用户行为</label><select onchange="channelDialogDraft.userBehavior=this.value"><option value="QUEUE"'+(ch.userBehavior!=='INTERRUPT'?' selected':'')+'>排队</option><option value="INTERRUPT"'+(ch.userBehavior==='INTERRUPT'?' selected':'')+'>打断</option></select><div class="toggle-desc">打断会先取消正在执行的会话，再处理新消息。</div></div></div>'+mappingSection+outboundTargetSection+'<div class="section-title">接收设置</div><div class="toggle-row"><div><div class="toggle-label">接收新消息</div><div class="toggle-desc">关闭后新消息不会进入智能体，主动发送不受影响。</div></div><label class="switch"><input type="checkbox" '+(ch.inboundEnabled!==false?'checked':'')+' onchange="channelDialogDraft.inboundEnabled=this.checked"><span class="slider"></span></label></div><div class="toggle-row"><div><div class="toggle-label">接收单聊消息</div><div class="toggle-desc">关闭后忽略用户单聊消息，群聊仍可正常使用。</div></div><label class="switch"><input type="checkbox" '+(ch.privateChatEnabled!==false?'checked':'')+' onchange="channelDialogDraft.privateChatEnabled=this.checked"><span class="slider"></span></label></div><div class="toggle-row"><div><div class="toggle-label">启用渠道</div></div><label class="switch"><input type="checkbox" '+(ch.enabled!==false?'checked':'')+' onchange="channelDialogDraft.enabled=this.checked"><span class="slider"></span></label></div>';
}

function channelConversationKey(type,id){return JSON.stringify([String(type||''),String(id||'').trim()])}
function channelMappingList(ch){var b=ch.binding;if(!b)return [];if(!Array.isArray(b.conversationMappings))b.conversationMappings=[];return b.conversationMappings}
function channelConversationTitle(item){var kind=item.chatType==='group'?'群聊':'单聊',name=String(item.displayName||'').trim(),id=String(item.id||'');if(!name||name==='未提供群名'||name==='历史会话')name=(name||'未命名会话')+' · '+id.slice(-8);return '['+kind+'] '+name}
function channelMappingKnown(mapping){return (channelDialogDraft.knownChatTargets||[]).filter(function(item){return item.chatType===mapping.chatType&&item.id===mapping.conversationId})[0]||{id:mapping.conversationId,chatType:mapping.chatType,displayName:'历史会话'}}
function channelMappingLabel(mapping){return mapping.conversationId?channelConversationTitle(channelMappingKnown(mapping)):''}
function channelMappingTooltip(mapping){if(!mapping.conversationId)return '';var item=channelMappingKnown(mapping);return channelConversationTitle(item)+(item.lastMessagePreview?'\n最新消息：'+item.lastMessagePreview:'')+'\n'+(item.chatType==='group'?'群 ID：':'用户 ID：')+item.id}
function channelMappingOptions(index,query){var mappings=channelMappingList(channelDialogDraft),mapping=mappings[index],selected=channelConversationKey(mapping.chatType,mapping.conversationId),needle=String(query||'').toLowerCase(),known=(channelDialogDraft.knownChatTargets||[]).slice();if(mapping.conversationId&&!known.some(function(item){return channelConversationKey(item.chatType,item.id)===selected}))known.unshift({id:mapping.conversationId,chatType:mapping.chatType,displayName:'历史会话'});var options=known.filter(function(item){var key=channelConversationKey(item.chatType,item.id),used=mappings.some(function(other,i){return i!==index&&channelConversationKey(other.chatType,other.conversationId)===key});return !used&&(!needle||(channelKnownTargetLabel(item)+' '+item.id).toLowerCase().indexOf(needle)>=0)}).map(function(item){var key=channelConversationKey(item.chatType,item.id);return '<button type="button" class="model-option" role="option" aria-selected="'+(key===selected)+'" data-key="'+esc(key)+'" onpointerdown="event.preventDefault()" onclick="chooseChannelMappingOption('+index+',this.dataset.key)"><span class="channel-conversation-heading"><span class="model-option-name">'+esc(channelConversationTitle(item))+'</span>'+(key===selected?'<span class="channel-conversation-selected" aria-label="已选中">✓</span>':'')+'</span>'+(item.lastMessagePreview?'<span class="model-option-detail channel-conversation-preview">最新消息：'+esc(item.lastMessagePreview)+'</span>':'')+'<span class="model-option-detail channel-conversation-id">'+(item.chatType==='group'?'群 ID：':'用户 ID：')+esc(item.id)+'</span></button>'}).join('');return options||'<div class="model-option-empty">'+(needle?'没有匹配的企微会话':'暂无可选择的企微会话')+'</div>'}
function refreshChannelMappingOptions(){if(!channelDialogDraft)return;channelMappingList(channelDialogDraft).forEach(function(mapping,index){var input=document.getElementById('channelMappingChat_'+index),menu=document.getElementById('channelMappingMenu_'+index);if(!input||!menu)return;var open=input.getAttribute('aria-expanded')==='true';menu.innerHTML=channelMappingOptions(index,open?input.dataset.query||'':'');input.title=channelMappingTooltip(mapping);if(!open)input.value=channelMappingLabel(mapping)})}
function openChannelMappingPicker(index){var input=document.getElementById('channelMappingChat_'+index);if(!input)return;input.closest('.model-combobox').classList.add('open');input.setAttribute('aria-expanded','true');input.dataset.query='';document.getElementById('channelMappingMenu_'+index).innerHTML=channelMappingOptions(index,'');input.select()}
function closeChannelMappingPicker(index){var input=document.getElementById('channelMappingChat_'+index);if(!input||!channelDialogDraft)return;input.closest('.model-combobox').classList.remove('open');input.setAttribute('aria-expanded','false');input.dataset.query='';input.value=channelMappingLabel(channelMappingList(channelDialogDraft)[index]);input.title=channelMappingTooltip(channelMappingList(channelDialogDraft)[index])}
function toggleChannelMappingPicker(index){var input=document.getElementById('channelMappingChat_'+index);if(input.getAttribute('aria-expanded')==='true'){closeChannelMappingPicker(index);return}input.focus();openChannelMappingPicker(index)}
function filterChannelMappingOptions(index,value){var input=document.getElementById('channelMappingChat_'+index);input.dataset.query=value;input.closest('.model-combobox').classList.add('open');input.setAttribute('aria-expanded','true');document.getElementById('channelMappingMenu_'+index).innerHTML=channelMappingOptions(index,value)}
function chooseChannelMappingOption(index,key){setChannelMappingConversation(index,key);closeChannelMappingPicker(index)}
function handleChannelMappingKey(index,event){if(event.key==='Escape'){event.preventDefault();closeChannelMappingPicker(index)}else if(event.key==='ArrowDown'){event.preventDefault();if(document.getElementById('channelMappingChat_'+index).getAttribute('aria-expanded')!=='true')openChannelMappingPicker(index);var first=document.getElementById('channelMappingMenu_'+index).querySelector('.model-option');if(first)first.focus()}else if(event.key==='Enter'){event.preventDefault();if(document.getElementById('channelMappingChat_'+index).getAttribute('aria-expanded')==='true'){var option=document.getElementById('channelMappingMenu_'+index).querySelector('.model-option');if(option)option.click()}}}
function renderChannelMappingPicker(index,mapping){return '<div class="model-combobox channel-conversation-picker" onfocusout="if(!this.contains(event.relatedTarget))closeChannelMappingPicker('+index+')"><input id="channelMappingChat_'+index+'" value="'+esc(channelMappingLabel(mapping))+'" title="'+esc(channelMappingTooltip(mapping))+'" placeholder="选择或搜索企微会话" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="channelMappingMenu_'+index+'" autocomplete="off" onfocus="openChannelMappingPicker('+index+')" onclick="openChannelMappingPicker('+index+')" oninput="filterChannelMappingOptions('+index+',this.value)" onkeydown="handleChannelMappingKey('+index+',event)"><button type="button" class="model-combobox-toggle" tabindex="-1" aria-label="展开企微会话列表" onpointerdown="event.preventDefault()" onclick="toggleChannelMappingPicker('+index+')"><span class="material-icons" aria-hidden="true">arrow_drop_down</span></button><div class="model-options" id="channelMappingMenu_'+index+'" role="listbox">'+channelMappingOptions(index,'')+'</div></div>'}
function setChannelMappingConversation(index,value){var mapping=channelMappingList(channelDialogDraft)[index];if(!value){mapping.chatType='';mapping.conversationId='';refreshChannelMappingOptions();return}var parts;try{parts=JSON.parse(value)}catch(e){return}var key=channelConversationKey(parts[0],parts[1]);if(channelMappingList(channelDialogDraft).some(function(other,i){return i!==index&&channelConversationKey(other.chatType,other.conversationId)===key})){showSnackbar('该企微会话已配置映射');refreshChannelMappingOptions();return}mapping.chatType=parts[0];mapping.conversationId=parts[1];refreshChannelMappingOptions()}
function renderChannelConversationMappings(ch,members){var items=channelMappingList(ch).map(function(mapping,index){var options='<option value="">选择团队成员</option>'+members.map(function(member){return '<option value="'+esc(member.id)+'"'+(member.id===mapping.teamMemberId?' selected':'')+'>'+esc(member.name||member.id)+' ['+esc(member.state||'UNKNOWN')+']</option>'}).join('');if(mapping.teamMemberId&&!members.some(function(member){return member.id===mapping.teamMemberId}))options+='<option value="'+esc(mapping.teamMemberId)+'" selected>当前成员（不可用）</option>';return '<div class="channel-target-item"><div class="grid-2"><div class="field-group"><label>企微会话 *</label>'+renderChannelMappingPicker(index,mapping)+'</div><div class="field-group"><label>团队成员 *</label><select onchange="channelDialogDraft.binding.conversationMappings['+index+'].teamMemberId=this.value">'+options+'</select></div></div><div class="channel-target-actions"><button type="button" class="btn btn-danger btn-sm" onclick="removeChannelConversationMapping('+index+')"><span class="material-icons">delete</span>删除</button></div></div>'}).join('');return '<div class="section-title">会话路由映射</div><div class="toggle-desc" style="margin-bottom:12px">仅选择本渠道收到过消息的企微会话；多个会话可以绑定同一成员。候选会话自动更新。未绑定会话将回复：当前企微会话尚未绑定智能体，请联系管理员配置会话路由。</div><div class="channel-target-list">'+(items||'<div class="filter-empty" style="padding:22px"><p>暂未配置会话映射</p></div>')+'</div><button type="button" class="btn btn-secondary btn-sm" style="margin-top:12px" onclick="addChannelConversationMapping()"><span class="material-icons">add</span>添加会话映射</button>'}
function addChannelConversationMapping(){channelMappingList(channelDialogDraft).push({chatType:'',conversationId:'',teamMemberId:''});renderChannelDialogBody()}
function removeChannelConversationMapping(index){channelMappingList(channelDialogDraft).splice(index,1);renderChannelDialogBody()}
function validateChannelConversationMappings(ch,team){var seen=[],members=team&&team.members||[],mappings=channelMappingList(ch);for(var i=0;i<mappings.length;i++){var mapping=mappings[i];mapping.conversationId=String(mapping.conversationId||'').trim();mapping.teamMemberId=String(mapping.teamMemberId||'').trim();if(['group','single'].indexOf(mapping.chatType)<0||!mapping.conversationId)return '请选择第 '+(i+1)+' 条映射的企微会话';if(!mapping.teamMemberId||!members.some(function(member){return member.id===mapping.teamMemberId}))return '请选择第 '+(i+1)+' 条映射的有效团队成员';var key=channelConversationKey(mapping.chatType,mapping.conversationId);if(seen.indexOf(key)>=0)return '同一个企微会话只能配置一条映射';seen.push(key)}return ''}

function setChannelDraftId(value){var previous=String(channelDialogDraft.id||'').trim(),targets=normalizeChannelOutboundTargets(channelDialogDraft);channelDialogDraft.id=value;if(targets.length===1&&String(targets[0].id||'').trim()===previous){targets[0].id=String(value||'').trim();var input=document.getElementById('channelOutboundTargetId_0');if(input)input.value=targets[0].id}}
function channelKnownTargetLabel(item){var kind=item&&item.chatType==='group'?'群聊':'单聊',name=String(item&&item.displayName||'未命名'),preview=String(item&&item.lastMessagePreview||'').trim();return '['+kind+'] '+name+(preview?' · 最新：'+preview:'')}
function channelOutboundTargetOptions(target,known){var selected=(known||[]).some(function(item){return item&&item.id===target.chatId}),options='<option value="">暂不选择企微会话</option>'+(known||[]).map(function(item){return '<option value="'+esc(item.id||'')+'"'+(item.id===target.chatId?' selected':'')+'>'+esc(channelKnownTargetLabel(item))+'</option>'}).join('');if(target.chatId&&!selected)options+='<option value="'+esc(target.chatId)+'" selected>历史目标（当前不可用）</option>';return options}
function renderChannelOutboundTargetList(ch){var configured=normalizeChannelOutboundTargets(ch),known=Array.isArray(ch.knownChatTargets)?ch.knownChatTargets:[],items=configured.map(function(target,index){return '<div class="channel-target-item"><div class="grid-2"><div class="field-group"><label>目标 ID *</label><input id="channelOutboundTargetId_'+index+'" maxlength="120" value="'+esc(target.id||'')+'" oninput="channelDialogDraft.outboundTargets['+index+'].id=this.value" placeholder="例如 release-group"></div><div class="field-group"><label>企微会话</label><select id="channelOutboundTargetChatId_'+index+'" onchange="channelDialogDraft.outboundTargets['+index+'].chatId=this.value">'+channelOutboundTargetOptions(target,known)+'</select></div></div><div class="field-group"><label>Agent 选择提示 *</label><textarea rows="2" maxlength="500" oninput="channelDialogDraft.outboundTargets['+index+'].description=this.value" placeholder="说明什么情况下应选择这个目标">'+esc(target.description||'')+'</textarea></div><div class="channel-target-actions"><button type="button" class="btn btn-danger btn-sm" onclick="removeChannelOutboundTarget('+index+')"><span class="material-icons">delete</span>删除</button></div></div>'}).join('');return '<div class="section-title">主动推送目标</div><div class="toggle-desc" style="margin-bottom:12px">Agent 仅在用户明确要求通知其他对象时，才会根据目标 ID 和提示选择。候选会话会在弹窗打开期间自动更新，最新来信排在最前。</div><div class="channel-target-list">'+(items||'<div class="filter-empty" style="padding:22px"><p>暂未配置主动推送目标</p></div>')+'</div><button type="button" class="btn btn-secondary btn-sm" style="margin-top:12px" onclick="addChannelOutboundTarget()"><span class="material-icons">add</span>添加推送目标</button>'}
function applyChannelKnownTargets(known){if(!channelDialogDraft)return false;var next=Array.isArray(known)?known:[],before=JSON.stringify(channelDialogDraft.knownChatTargets||[]);if(before===JSON.stringify(next))return false;channelDialogDraft.knownChatTargets=JSON.parse(JSON.stringify(next));var configured=normalizeChannelOutboundTargets(channelDialogDraft);configured.forEach(function(target,index){var select=document.getElementById('channelOutboundTargetChatId_'+index);if(select)select.innerHTML=channelOutboundTargetOptions(target,next)});refreshChannelMappingOptions();return true}
async function refreshChannelKnownTargets(){if(channelDialogMode!=='edit'||!channelDialogDraft||!channelDialogSourceId)return;var request=++channelKnownTargetsRequest;try{var response=await api('/api/config'),latest=await response.json();if(request!==channelKnownTargetsRequest||!channelDialogDraft)return;var channel=(latest.channels||[]).filter(function(item){return String(item.id||'').trim()===channelDialogSourceId})[0];if(!channel)return;if(applyChannelKnownTargets(channel.knownChatTargets||[])){var current=(config.channels||[]).filter(function(item){return String(item.id||'').trim()===channelDialogSourceId})[0];if(current)current.knownChatTargets=JSON.parse(JSON.stringify(channel.knownChatTargets||[]))}}catch(e){}}
function startChannelKnownTargetsRefresh(){stopChannelKnownTargetsRefresh();if(channelDialogMode!=='edit'||!channelDialogSourceId)return;refreshChannelKnownTargets();channelKnownTargetsTimer=setInterval(refreshChannelKnownTargets,2000)}
function stopChannelKnownTargetsRefresh(){if(channelKnownTargetsTimer)clearInterval(channelKnownTargetsTimer);channelKnownTargetsTimer=0;channelKnownTargetsRequest+=1}
