function removeChannelOutboundTarget(index){normalizeChannelOutboundTargets(channelDialogDraft).splice(index,1);renderChannelDialogBody()}
function setChannelDraftBindingType(type){var b=channelDialogDraft.binding;b.type=type;b.instanceId=channelRuntime.instanceId||((curInstance&&curInstance.instanceId)||'');if(type==='MAIN'){b.teamId='';b.teamMemberId='';b.teamMemberSelection='FIXED';b.conversationMappings=[]}else{b.groupId='';b.teamMemberSelection=b.teamMemberSelection||'FIXED'}renderChannelDialogBody()}
function setChannelDraftTeam(teamId){var b=channelDialogDraft.binding,team=(channelBindingTargets.teams||[]).filter(function(item){return item.id===teamId})[0];b.teamId=teamId;b.conversationMappings=[];b.teamMemberId='';b.teamMemberSelection='FIXED';if(team&&(team.mode||'NORMAL')==='CAPTAIN')b.teamMemberId=team.captainTeamMemberId||'';renderChannelDialogBody()}
function setChannelDraftMemberSelection(selection){channelDialogDraft.binding.teamMemberSelection=selection||'FIXED';if(selection!=='FIXED')channelDialogDraft.binding.teamMemberId='';renderChannelDialogBody()}
function showChannelDialogValidation(id,message){var input=document.getElementById(id);if(input){input.classList.add('field-invalid');input.focus()}showSnackbar(message)}
async function saveChannelDialog(){
var ch=channelDialogDraft,b=ch&&ch.binding;if(!ch||!b)return;ch.id=String(ch.id||'').trim();ch.botId=String(ch.botId||'').trim();ch.secret=String(ch.secret||'');ch.wsUrl=String(ch.wsUrl||'').trim()||'wss://openws.work.weixin.qq.com';b.instanceId=channelRuntime.instanceId||((curInstance&&curInstance.instanceId)||'');
if(!ch.id){showChannelDialogValidation('channelDraftId','渠道名称不能为空');return}if((config.channels||[]).some(function(item,index){return index!==channelDialogIndex&&String(item.id||'').trim()===ch.id})){showChannelDialogValidation('channelDraftId','渠道名称已存在');return}if(!ch.botId){showChannelDialogValidation('channelDraftBotId','Bot ID 不能为空');return}if(!ch.secret){showChannelDialogValidation('channelDraftSecret','Secret 不能为空');return}
var usedTargetIds=[];(config.channels||[]).forEach(function(item,index){if(index===channelDialogIndex)return;normalizeChannelOutboundTargets(item).forEach(function(target){var id=String(target&&target.id||'').trim();if(id)usedTargetIds.push(id)})});var localTargetIds=[];for(var targetIndex=0;targetIndex<normalizeChannelOutboundTargets(ch).length;targetIndex++){var target=ch.outboundTargets[targetIndex];target.id=String(target.id||'').trim();target.chatId=String(target.chatId||'').trim();target.description=String(target.description||'').trim();if(!isValidChannelOutboundTargetId(target.id)){showChannelDialogValidation('channelOutboundTargetId_'+targetIndex,'目标 ID 只能包含中文、字母、数字、下划线和短横线');return}if(localTargetIds.indexOf(target.id)>=0||usedTargetIds.indexOf(target.id)>=0){showChannelDialogValidation('channelOutboundTargetId_'+targetIndex,'主动推送目标 ID 已存在');return}if(!target.description){showSnackbar('请填写目标「'+target.id+'」的 Agent 选择提示');return}localTargetIds.push(target.id)}delete ch.defaultChatId;
if(b.type==='MAIN'){b.teamId='';b.teamMemberId='';b.teamMemberSelection='FIXED';b.conversationMappings=[];if(!b.groupId){showSnackbar('请选择处理消息的智能体');return}}else if(b.type==='TEAM_MEMBER'){b.groupId='';if(!b.teamId){showSnackbar('请选择 Fast Team');return}var selectedTeam=(channelBindingTargets.teams||[]).filter(function(item){return item.id===b.teamId})[0];if(selectedTeam&&(selectedTeam.mode||'NORMAL')==='CAPTAIN'){b.teamMemberSelection='FIXED';b.teamMemberId=selectedTeam.captainTeamMemberId||''}if((b.teamMemberSelection||'FIXED')==='FIXED'&&!b.teamMemberId){showSnackbar('请选择团队成员');return}if(b.teamMemberSelection!=='FIXED')b.teamMemberId='';if(b.teamMemberSelection==='CONVERSATION_MAPPING'){var mappingError=validateChannelConversationMappings(ch,selectedTeam);if(mappingError){showSnackbar(mappingError);return}}else b.conversationMappings=[]}else{showSnackbar('请选择消息处理方式');return}
var saved=JSON.parse(JSON.stringify(ch)),runtimeId=channelDialogIndex>=0?(config.channels[channelDialogIndex]._runtimeId||config.channels[channelDialogIndex].id||''):'',previous=channelDialogIndex>=0?config.channels[channelDialogIndex]:null,insertIndex=channelDialogIndex>=0?channelDialogIndex:config.channels.length,wasDirty=dirty,button=document.getElementById('channelDialogSubmit');Object.defineProperty(saved,'_runtimeId',{value:runtimeId,writable:true,enumerable:false});
if(channelDialogIndex>=0)config.channels[channelDialogIndex]=saved;else config.channels.push(saved);markDirty();button.disabled=true;var ok=await saveConfig(true);button.disabled=false;if(!ok){if(previous)config.channels[insertIndex]=previous;else config.channels.splice(insertIndex,1);dirty=wasDirty;return}if(channelDialogIndex<0)listState.channel.page=Math.max(1,Math.ceil(config.channels.length/listState.channel.pageSize));channelDialogDraft=null;closeDialog('channelDialog');renderChannels();showSnackbar(channelDialogMode==='copy'?'消息渠道已复制并保存':(channelDialogMode==='edit'?'消息渠道已更新并保存':'消息渠道已创建并保存'));applyChannelConfig(insertIndex).then(function(){showSnackbar('消息渠道已自动刷新并开启')}).catch(function(e){showSnackbar('消息渠道已保存，但自动刷新失败：'+e.message)});
}
async function deleteChannel(i){
var channel=config.channels[i];if(!channel||!await showConfirm('删除消息渠道「'+(channel.id||'未命名渠道')+'」后将立即保存配置。',{title:'删除消息渠道？',confirmText:'删除渠道',danger:true}))return;var wasDirty=dirty;config.channels.splice(i,1);markDirty();var ok=await saveConfig(true);if(!ok){config.channels.splice(i,0,channel);dirty=wasDirty;renderChannels();return}renderChannels();showSnackbar('消息渠道已删除并保存');
}

async function applyChannelConfig(i){
var ch=config.channels[i];if(!ch)throw new Error('消息渠道不存在');
if(!Object.prototype.hasOwnProperty.call(ch,'_runtimeId'))Object.defineProperty(ch,'_runtimeId',{value:ch.id||'',writable:true,enumerable:false});
var previousId=ch._runtimeId||'',channelId=(ch.id||'').trim();
markItemRefreshing('channels',channelId);try{var r=await api('/api/refresh-channel',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({previousChannelId:previousId,channelId:channelId})});var d=await r.json();
if(!r.ok||!d.ok)throw new Error(d.error||'刷新失败');ch._runtimeId=channelId;await loadChannelStatus();return d}
finally{await loadItemRefreshStatus(false);renderChannels()}
}
async function refreshChannel(i,btn){
var ch=config.channels[i];if(!ch)return;
if(itemOperationPending('channels',ch.id||'')){showSnackbar(itemRefreshMessage('channels',ch.id||''));return}
if(!await showConfirm('将保存当前配置并应用到渠道「'+(ch.id||'')+'」，其他渠道不会受到影响。',{title:'保存并应用到渠道？',confirmText:'保存并应用'}))return;
btn.disabled=true;btn.innerHTML='<span class="material-icons">hourglass_top</span>';
var ok=await saveConfig(true);
if(!ok){btn.disabled=false;btn.innerHTML='<span class="material-icons">refresh</span>';return}
try{await applyChannelConfig(i);showSnackbar('配置已保存并应用到渠道「'+(ch.id||'').trim()+'」')}
catch(e){showSnackbar('渠道应用失败:'+e.message)}
finally{btn.disabled=false;btn.innerHTML='<span class="material-icons">refresh</span>'}
}

async function refreshChannelStatuses(){
await loadChannelStatus();
(config.channels||[]).forEach(function(ch,i){
var runtimeId=ch._runtimeId;
var status=document.getElementById('channelStatus_'+i);if(status){var value=(channelRuntime.statuses&&channelRuntime.statuses[runtimeId])||'STOPPED';status.textContent=value;status.className='status-badge '+normalized(value)}
var error=document.getElementById('channelError_'+i);if(error){var message=(channelRuntime.errors&&channelRuntime.errors[runtimeId])||'';error.textContent=message||'企业微信 · WebSocket';error.title=message;error.className='agent-engine'+(message?' channel-error':'')}
});
}
async function deleteRobot(i){
var robot=config.robots[i];if(robot&&robot.agentProvider==='REMOTE_STARCORE_ACP'&&robot.enabled!==false){showSnackbar('生效的远程星核不能删除，请先断开连接，失效后再删除');return}if(!robot||!await showConfirm('删除智能体「'+(robot.name||'')+'」后将立即保存配置。',{title:'删除智能体？',confirmText:'删除智能体',danger:true}))return;var wasDirty=dirty;config.robots.splice(i,1);markDirty();var ok=await saveConfig(true);if(!ok){config.robots.splice(i,0,robot);dirty=wasDirty;render();return}render();showSnackbar('智能体已删除并保存');
}
async function toggleRobot(i,enabled){
var robot=config.robots[i];if(!robot)return;if(robot.agentProvider==='REMOTE_STARCORE_ACP'){showSnackbar('远程星核状态由连接自动维护');renderRobots();return}var key=robot.name||'';
if(itemOperationPending('robots',key)){renderRobots();showSnackbar(itemRefreshMessage('robots',key));return}
var previous=robot.enabled!==false,wasDirty=dirty;robot.enabled=enabled;markDirty();setItemTogglePending('robots',key,true);
var ok=await saveConfig(true);if(!ok){robot.enabled=previous;dirty=wasDirty;setItemTogglePending('robots',key,false);return}
try{await applyRobotConfig(i);showSnackbar('智能体「'+key+'」已'+(enabled?'启用':'停用')+'并自动刷新')}
catch(e){showSnackbar('智能体「'+key+'」已保存，但自动刷新失败：'+e.message)}
finally{setItemTogglePending('robots',key,false)}
}

function nextRobotCopyName(sourceName){
var source=String(sourceName||'智能体').trim()||'智能体',match=source.match(/^(.*)-(\d+)$/),base=match?match[1]:source,next=match?parseInt(match[2],10)+1:1,names=(config.robots||[]).map(function(robot){return String(robot.name||'').trim()});
var candidate=base+'-'+next;while(names.indexOf(candidate)>=0){next+=1;candidate=base+'-'+next}return candidate;
}
